let h=`<div class="stats"><div><b>${act.length}</b>eventos</div><div><b>${R$(rec)}</b>recebido</div><div><b>${R$(tot-rec)}</b>a receber</div></div>
<div class="fl">${[['all','Todos'],['up','Próximos'],['30','Próx. 30 dias'],['mo','Este mês'],['past','Passados']].map(([k,l])=>`<span class="chip ${pc==k?'on':''}" onclick="setF('${k}')">${l}</span>`).join('')}</div>
<div class="fl">${ms.map(m=>`<span class="chip ${AF.m==m?'on':''}" onclick="setM('${m}')">${fd(m+'-01',{month:'short',year:'2-digit'})}</span>`).join('')}</div>
<div class="g2"><label>De<input type="date" value="${AF.de}" onchange="setR('de',this.value)"></label><label>Até<input type="date" value="${AF.ate}" onchange="setR('ate',this.value)"></label></div>
<p class="mut" style="font-size:12px">${L.length} de ${all.length} eventos ${L.length<all.length?'<button style="padding:2px 8px;font-size:12px" onclick="setF(\'all\')">Limpar filtro</button>':''}</p>`;
